import os,json,subprocess,datetime
from pathlib import Path
started=datetime.datetime.now(datetime.timezone.utc).isoformat()
repo=Path.home()/'repos/touristic-digital-platform.git'
branch='refs/heads/chore/journey-audit-coverage-admission-20261031'
claim='MD-JOURNEY-AUDIT-COVERAGE-ADMISSION-20261031'
def out(args):
 return subprocess.check_output(args,text=True).strip()
def api(path):
 return json.loads(out(['gh','api',path]))
worktree_text=out(['git','--git-dir='+str(repo),'worktree','list','--porcelain'])
matched=[]
for block in worktree_text.split('\n\n'):
 lines=block.splitlines()
 if 'branch '+branch in lines:
  item=dict(line.split(' ',1) for line in lines if ' ' in line)
  item['statusPorcelain']=out(['git','--no-optional-locks','-C',item['worktree'],'status','--porcelain'])
  matched.append(item)
ancestors=set()
pid=os.getpid()
while pid and pid not in ancestors:
 ancestors.add(pid)
 try:
  line=next(x for x in Path('/proc',str(pid),'status').read_text().splitlines() if x.startswith('PPid:'))
  pid=int(line.split()[1])
 except (OSError,StopIteration,ValueError):
  break
processes=[]; unreadable_cwd=0; unreadable_cmdline=0; scanned=0; probe_matches=[]
for proc in Path('/proc').iterdir():
 if not proc.name.isdigit(): continue
 scanned+=1; pid=int(proc.name); cwd=None; cmdline=None
 try: cwd=os.readlink(proc/'cwd')
 except (OSError,PermissionError): unreadable_cwd+=1
 try: cmdline=(proc/'cmdline').read_bytes().decode('utf-8','replace')
 except (OSError,PermissionError): unreadable_cmdline+=1
 reasons=[]
 if cwd is not None and any(cwd==item.get('worktree') or cwd.startswith(item.get('worktree','!')+'/') for item in matched): reasons.append('cwd_in_matching_worktree')
 if cmdline is not None and (branch in cmdline or claim in cmdline): reasons.append('exact_claim_or_branch_marker')
 if not reasons: continue
 try: name=(proc/'comm').read_text().strip()
 except OSError: name=None
 row={'pid':pid,'name':name,'cwd':cwd,'matchReasons':reasons,'fullArgumentsOmitted':True}
 if pid in ancestors: probe_matches.append(row)
 else: processes.append(row)
pr=api('repos/luizanunciostoca/touristic-digital-platform/pulls/1337')
main=api('repos/luizanunciostoca/touristic-digital-platform/git/ref/heads/main')
backup=api('repos/luizanunciostoca/touristic-digital-platform/git/ref/heads/archive/audit-coverage-renewal-20261031-222400-f25b97cd')
tree=out(['git','--git-dir='+str(repo),'rev-parse',pr['head']['sha']+'^{tree}'])
print(json.dumps({
 'kind':'NATIVE_SCOPED_READ_ONLY_RETIREMENT_PREPARATION_INVENTORY',
 'startedAt':started,'observedAt':datetime.datetime.now(datetime.timezone.utc).isoformat(),
 'branch':branch,'claimId':claim,
 'pr':{'number':pr['number'],'state':pr['state'],'draft':pr['draft'],'headSha':pr['head']['sha'],'baseSha':pr['base']['sha'],'treeShaFromBareStore':tree},
 'canonicalMainSha':main['object']['sha'],'previousBackupSha':backup['object']['sha'],
 'matchingMaterialWorktrees':matched,'matchingProcessesExcludingThisProbeAndAncestors':processes,
 'processesScanned':scanned,'unreadableCwdCount':unreadable_cwd,'unreadableCmdlineCount':unreadable_cmdline,
 'thisReadOnlyProbeAndAncestorPids':sorted(ancestors),'probeMarkerMatches':probe_matches,
 'bareStorePresent':repo.is_dir(),'mutationsExecuted':[],
 'limits':['Current PID/cwd and exact branch/claim markers only; inaccessible processes remain unknown.','No global absence assertion; no inference that unrelated open GitHub jobs are running or drained.','This inventory command is an observed read-only controller child until the signed Native result reports completion.']
},ensure_ascii=False,indent=2))
